function ProductCard({ p, addToCart }) {
  return (
    <div style={{
      border: "1px solid #eee",
      padding: 15,
      width: 220,
      borderRadius: 10,
      background: "#fff",
      transition: "0.3s"
    }}>
      <img src={p.image} width="100%" />

      <h4>{p.name}</h4>

      <p style={{
        color: "red",
        fontWeight: "bold"
      }}>
        {p.price.toLocaleString()} VND
      </p>

      <button 
        onClick={() => addToCart(p)}
        style={{
          background: "#ff6600",
          color: "white",
          border: "none",
          padding: 10,
          width: "100%",
          borderRadius: 5
        }}
      >
        🛒 Mua ngay
      </button>
    </div>
  );
}

export default ProductCard;
